-- Matriz Atricon do Poder Legislativo: 83 critérios da avaliação de 2026, com os links do site da Câmara.
-- Rodar uma vez no SQL Editor do banco analítico. Rodar de novo não apaga o que foi editado no painel.
-- Com link cadastrado não significa critério atendido: o resultado oficial é o do Radar da Transparência Pública.

alter table public.atricon_itens add column if not exists classificacao text;
alter table public.atricon_itens add column if not exists links jsonb not null default '[]'::jsonb;
create unique index if not exists atricon_itens_numero_idx on public.atricon_itens (numero);

on conflict (numero) do nothing;

on conflict (chave) do nothing;
